suppressPackageStartupMessages({
  library(Seurat)
  library(Matrix)
})

# Space Ranger output directories for the four spatial transcriptomics samples.
# Each directory should contain outs/filtered_feature_bc_matrix.h5 and the
# corresponding spatial image files generated by Space Ranger.
space_ranger_outs <- c(
  O = "data/O/outs",
  P = "data/P/outs",
  C = "data/C/outs",
  U = "data/U/outs"
)

read_and_filter_spatial <- function(outs_dir, sample_id) {
  st <- Load10X_Spatial(
    data.dir = outs_dir,
    filename = "filtered_feature_bc_matrix.h5",
    assay = "Spatial",
    slice = sample_id
  )

  counts <- GetAssayData(st, assay = "Spatial", slot = "counts")
  keep_genes <- rownames(counts)[Matrix::rowSums(counts > 0) >= 3]
  st <- subset(st, features = keep_genes)
  st <- subset(st, subset = nFeature_Spatial >= 200)
  st$sample_id <- sample_id
  st
}

st_list <- Map(read_and_filter_spatial, space_ranger_outs, names(space_ranger_outs))
names(st_list) <- names(space_ranger_outs)

st <- merge(
  x = st_list[[1]],
  y = st_list[-1],
  add.cell.ids = names(st_list),
  project = "melon_spatial_transcriptomics"
)

st <- SCTransform(st, assay = "Spatial", verbose = FALSE)
DefaultAssay(st) <- "SCT"
st <- RunPCA(st, assay = "SCT", verbose = FALSE)
st <- FindNeighbors(st, dims = 1:40)
st <- FindClusters(st, resolution = 0.9)
st <- RunUMAP(st, dims = 1:40, verbose = FALSE)

st_markers <- FindAllMarkers(
  st,
  test.use = "wilcox",
  logfc.threshold = 0.1,
  min.pct = 0.25
)

write.csv(st_markers, "spatial_markers.csv", row.names = FALSE)
saveRDS(st, "ST_snRNA.rds")
